mapper.sql:




FROM mes_material_issue_input f JOIN wm_stock_document d ON d.id=f.document_id AND d.source_execution_code=f.execution_code
WHERE d.source_workorder_id=#{workorderId} AND f.input_kind=#{enumProductionInput} AND f.confirmed_at IS NOT NULL
  AND f.stock_applied=TRUE AND f.source_mode=#{enumLocalOnly} AND d.document_type=#{enumMaterialIssue} AND d.status=#{enumPosted}
